package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.AccountLocking;
import hu.bankmonitor.payments.accounts.LockedAccounts;
import hu.bankmonitor.payments.common.Money;
import hu.bankmonitor.payments.transfers.checks.CheckLedger;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Requests a Transfer: funds reserved on the source Account, nothing moved, and a {@code
 * PENDING} Transfer to hold the request while its Checks are outstanding.
 *
 * <p><b>The order inside {@link #reserve} is the correctness argument</b>, and it is the
 * reason the three statements are not interchangeable:
 *
 * <ol>
 * <li>lock both Accounts, ascending by ID, which {@link AccountLocking} owns;
 * <li><em>then</em> read the source Account's Available Balance and test the amount against
 * it;
 * <li>write the reservation, the Transfer, and the Check Ledger the Transfer will be
 * settled or rejected against.
 * </ol>
 *
 * <p>Because the check follows the lock, the figure it tests against cannot be invalidated
 * between reading it and acting on it: any other transaction that would spend the same
 * Available Balance is waiting on the row until this one commits, and then reads what this
 * one wrote. Checking first and locking second would compile, pass every single-threaded
 * test, and overdraw under load.
 *
 * <p>Nothing here saves the source Account, and that is not an omission. The Accounts come
 * back from {@link AccountLocking} attached to this transaction's persistence context, so
 * raising the Reserved Amount <em>is</em> the write, flushed on commit alongside the
 * Transfer. There is no other way for this slice to do it either: design decision 30 keeps
 * {@code AccountRepository} package-private, and locking is the whole of what {@code
 * accounts} exports.
 *
 * <p>The Exchange Rate is deliberately not fetched here. Design decision 4 puts it in a
 * phase of its own with no transaction open and no locks held, which is what makes
 * pessimistic locking affordable at all; {@code LockedPathTouchesOnlyTheDatabaseTest} names
 * this class and fails if anything it can reach would wait on a provider.
 *
 * <p><b>Same-Currency Transfers only, and not by a check.</b> Both amounts on the Transfer
 * are denominated by the source Account, so a Transfer between two Currencies is reserved
 * and written with the wrong Currency in the credited column rather than refused. That hole
 * is deliberate and named in {@code docs/deferred.md}: ticket 26 is where an Exchange Rate
 * gives the credited side a figure of its own, and a refusal added here now is a rule ticket
 * 26 would have to reinterpret rather than delete.
 */
@Service
class FundsReservation {

	private final AccountLocking accounts;

	private final TransferRepository transfers;

	private final CheckLedger ledger;

	FundsReservation(AccountLocking accounts, TransferRepository transfers, CheckLedger ledger) {
		this.accounts = accounts;
		this.transfers = transfers;
		this.ledger = ledger;
	}

	/**
	 * Reserves the amount on the source Account and records the {@code PENDING} Transfer it
	 * is held for, in one transaction that writes both or neither.
	 *
	 * <p>The transaction is opened here rather than inherited, which is what {@link
	 * AccountLocking}'s mandatory propagation is checking for. Ticket 16 will widen it to
	 * carry the idempotency record's flip to {@code SUCCEEDED} in the same commit, per
	 * design decision 4.
	 *
	 * <p>The Check Ledger is opened last because its rows point at the Transfer's ID, and
	 * inside the same transaction because a {@code PENDING} Transfer with an empty Check
	 * Ledger is one nothing will ever settle, expire or explain. {@link CheckLedger#openFor}
	 * refuses to run without a transaction, and refuses to open a ledger with no Checks in
	 * it, so the ordering is the only part of that left here.
	 *
	 * @throws hu.bankmonitor.payments.accounts.UnknownAccountException  if either Account ID
	 *                                                                  has no row
	 * @throws hu.bankmonitor.payments.accounts.InsufficientFundsException if the source
	 *                                                                  Account's Available
	 *                                                                  Balance does not
	 *                                                                  cover the amount
	 * @throws IllegalArgumentException if both IDs name the same Account
	 */
	@Transactional
	public Transfer reserve(ReservationRequest request) {
		LockedAccounts locked =
				accounts.lockForTransfer(request.sourceAccountId(), request.destinationAccountId());
		Money amount = new Money(request.amountMinorUnits(), locked.source().getCurrency());

		locked.source().reserve(amount);

		Transfer requested = transfers.save(new Transfer(request.sourceAccountId(),
				request.destinationAccountId(), amount, amount, request.requestedAt()));
		ledger.openFor(requested);
		return requested;
	}
}

package hu.bankmonitor.payments.transfers;

import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.Repository;

import java.util.Optional;

import static jakarta.persistence.LockModeType.PESSIMISTIC_WRITE;

/**
 * Reading a {@link Transfer} and advancing it, package-private so that reaching it from
 * another slice does not compile (design decision 30). Writing one is
 * {@link TransferCreation}'s, and the split is deliberate — that interface says why.
 *
 * <p>The bare {@link Repository} marker rather than {@code JpaRepository}, on
 * {@link hu.bankmonitor.payments.accounts.Account}'s precedent: it declares nothing, so
 * every method here is one with a call site today. The status filter and the newest-first
 * listing arrive with ticket 15, and the reaper's overdue scan with ticket 23.
 */
interface TransferRepository extends Repository<Transfer, Long> {

	/** One Transfer by ID, empty when no such Transfer was ever requested. */
	Optional<Transfer> findById(Long id);

	/**
	 * Reads one Transfer and holds a row lock on it until the surrounding transaction ends,
	 * so that everything deciding this Transfer's next status is serialised behind it.
	 *
	 * <p><b>This is what makes concurrent Verdicts safe, and the guarded update below is
	 * not.</b> Two Verdicts arriving together each write their own ledger row, and neither
	 * transaction can see the other's until it commits — so both read a ledger with one
	 * Check still outstanding, both decide to wait, and the Transfer stays {@code PENDING}
	 * for ever against a fully approved ledger, holding the operator's funds. No guard on
	 * the {@code UPDATE} helps, because neither transaction ever reaches one. Only taking
	 * this lock before touching the ledger does.
	 *
	 * <p>{@link LockModeType#PESSIMISTIC_WRITE} is what turns the {@code select} into a
	 * {@code select … for update}, exactly as on {@code AccountRepository}. The lock order
	 * for anything that holds both is <b>Transfer first, then Accounts ascending</b>; it is
	 * acyclic against the reservation, which takes Account locks only and never waits on a
	 * Transfer row that already exists.
	 */
	@Lock(PESSIMISTIC_WRITE)
	Optional<Transfer> findAndLockById(Long id);

	/**
	 * Moves a {@code PENDING} Transfer to a terminal status, and reports whether it was this
	 * caller that moved it — one row when the Transfer was still pending, none when it was
	 * not.
	 *
	 * <p>The transition carries its own precondition rather than trusting the caller to have
	 * checked one. Under the row lock above it cannot fail, and that is the point of writing
	 * it this way: a future caller that reached this method without the lock fails loudly
	 * instead of settling a Transfer that somebody else already settled. It is the same
	 * shape as the idempotency record's claim and the expiry reaper's sweep — one idea used
	 * three times, not three mechanisms.
	 *
	 * <p>A bulk update rather than a mutator on the entity, for {@code CheckLedgerEntry}'s
	 * reason: a setter would offer a second way to make this transition that quietly is not
	 * atomic. {@link Transfer} therefore has none.
	 */
	@Modifying
	@Query("""
			UPDATE Transfer transfer SET transfer.status = :terminalStatus
			WHERE transfer.id = :id
			  AND transfer.status = hu.bankmonitor.payments.transfers.TransferStatus.PENDING
			""")
	int advanceFromPending(Long id, TransferStatus terminalStatus);
}

package hu.bankmonitor.payments.transfers;

import org.springframework.data.repository.Repository;

/**
 * The one way a {@link Transfer} comes into being, on an interface of its own so that
 * "exactly one class may write a Transfer" is a claim a rule can be pointed at.
 *
 * <p>Splitting it off {@link TransferRepository} costs an interface and buys the difference
 * between two kinds of access. Creating a Transfer is restricted, because a Transfer written
 * anywhere but {@link FundsReservation} would be {@code PENDING} against an empty Check
 * Ledger — the state the whole design is arranged to prevent, and the one
 * {@code NothingButTheReservationCreatesATransferTest} aims at this interface. Reading one,
 * and advancing one by a guarded update, are not restricted at all: the guard travels with
 * the statement, so a second caller cannot make the transition twice however it reached it.
 *
 * <p>Before ticket 20 both lived on {@code TransferRepository} and the rule was aimed there,
 * which held only while the reservation was the sole caller of anything about a Transfer.
 * The alternative — an allow-list of classes permitted to hold the repository — is a
 * structural claim degraded into a list every later ticket appends to.
 */
interface TransferCreation extends Repository<Transfer, Long> {

	/** Writes one Transfer, which is how a Transfer comes to exist. */
	Transfer save(Transfer transfer);
}

