package hu.bankmonitor.payments.accounts;

import hu.bankmonitor.payments.common.Currency;
import hu.bankmonitor.payments.common.Money;
import jakarta.persistence.AttributeOverride;
import jakarta.persistence.Column;
import jakarta.persistence.Embedded;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.Objects;

/**
 * A balance held in one currency, and the part of it already committed to transfers that
 * have not finished.
 *
 * <p>The atomic entity of this context: nothing owns an Account. {@code User} is named in
 * {@code CONTEXT.md} as deliberately unmodelled, and design decision 1 has why.
 *
 * <p><b>Two figures rather than one</b>, per design decision 13. The balance is what the
 * Account holds; the Reserved Amount is what is spoken for. Their difference is the
 * {@linkplain #getAvailableBalance() Available Balance}, which is what an overdraft check
 * tests against — so an Account's own row answers "how much of this is still spendable"
 * without reading a single transfer. Reserving raises the Reserved Amount, settling lowers
 * both, and rejection or expiry lowers only the Reserved Amount.
 *
 * <p>The currency is fixed at creation and there is no way to change it: an Account that
 * could be redenominated would make every historical balance ambiguous. Both figures carry
 * it because both are {@link Money}, and {@link #getCurrency()} is the single answer they
 * are constructed to agree on.
 */
@Entity
@Table(name = "accounts")
public class Account {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	@Embedded
	@AttributeOverride(name = "minorUnits", column = @Column(name = "balance_minor_units"))
	@AttributeOverride(name = "currency", column = @Column(name = "balance_currency"))
	private Money balance;

	@Embedded
	@AttributeOverride(name = "minorUnits", column = @Column(name = "reserved_amount_minor_units"))
	@AttributeOverride(name = "currency", column = @Column(name = "reserved_amount_currency"))
	private Money reservedAmount;

	protected Account() {
		// required by JPA
	}

	/**
	 * Opens an Account holding the given amount, with nothing reserved against it. The
	 * opening balance carries the currency, so there is no way to name one that disagrees
	 * with the other figure.
	 */
	public Account(Money openingBalance) {
		this.balance = Objects.requireNonNull(openingBalance, "an account opens with a balance");
		this.reservedAmount = Money.zero(openingBalance.currency());
	}

	public Long getId() {
		return id;
	}

	/** Everything the Account holds, including the part already spoken for. */
	public Money getBalance() {
		return balance;
	}

	/** The part of the balance committed to transfers that have not reached a terminal state. */
	public Money getReservedAmount() {
		return reservedAmount;
	}

	/** What the Account can still spend, and the figure an overdraft check tests against. */
	public Money getAvailableBalance() {
		return balance.minus(reservedAmount);
	}

	/** Fixed when the Account was opened. Both figures are denominated in it. */
	public Currency getCurrency() {
		return balance.currency();
	}

	/**
	 * Commits part of the Available Balance to a Transfer that has not settled: the Reserved
	 * Amount rises by the amount, the balance does not move, and nothing is credited
	 * anywhere. Settling the Transfer lowers both figures; rejecting or expiring it lowers
	 * only the Reserved Amount.
	 *
	 * <p>The refusal lives here rather than in the caller, so that there is no way to reach a
	 * balance and overdraw it. What does <em>not</em> live here is whether it was safe to
	 * ask: this method compares two figures it was handed, and that the Account's row is
	 * locked while it does so is the caller's obligation — design decision 6 is why. Called
	 * against an unlocked Account the arithmetic is still right and the answer is still
	 * worthless, because another transaction may have spent the same Available Balance in
	 * between.
	 *
	 * @throws InsufficientFundsException if the Available Balance does not cover the amount
	 * @throws IllegalArgumentException   if the amount is in another Currency
	 */
	public void reserve(Money amount) {
		Money availableBalance = getAvailableBalance();
		if (availableBalance.isLessThan(amount)) {
			throw new InsufficientFundsException(availableBalance, amount);
		}
		reservedAmount = reservedAmount.plus(amount);
	}

	/**
	 * Pays a Transfer this Account had reserved for: the balance falls by the amount and the
	 * Reserved Amount falls with it, because the reservation is consumed rather than left
	 * behind. The Available Balance therefore does not move — the money was already spoken
	 * for, and settling is where it actually leaves.
	 *
	 * <p><b>Both figures, and that is the whole reason this is one method.</b> A debit
	 * without the matching consumption would pass every balance assertion and leave the
	 * Account holding a reservation for a Transfer that is finished, so every later overdraft
	 * check would test against a figure short by it, for ever.
	 *
	 * @throws IllegalArgumentException if the amount exceeds the Reserved Amount, or is in
	 *                                  another Currency
	 */
	public void settle(Money amount) {
		reservedAmount = reservedAmount.minus(withinTheReservedAmount(amount));
		balance = balance.minus(amount);
	}

	/**
	 * Gives up a reservation without moving money, which is what all three of rejection,
	 * expiry and any later cancellation do: the Reserved Amount falls, the balance does not,
	 * and the Available Balance rises back to where it was before the Transfer was requested.
	 *
	 * @throws IllegalArgumentException if the amount exceeds the Reserved Amount, or is in
	 *                                  another Currency
	 */
	public void release(Money amount) {
		reservedAmount = reservedAmount.minus(withinTheReservedAmount(amount));
	}

	/**
	 * Receives a settled Transfer. Nothing is reserved on the receiving side — the money
	 * arrives owing nobody anything — so the balance and the Available Balance rise together,
	 * and there is no figure this could be asked to overdraw.
	 *
	 * @throws IllegalArgumentException if the amount is in another Currency
	 */
	public void credit(Money amount) {
		balance = balance.plus(amount);
	}

	/**
	 * The one refusal both outward movements share: neither may take the Reserved Amount
	 * below zero. An Account that could would go on to report an Available Balance larger
	 * than it holds, and the next reservation would overdraw against the excess.
	 *
	 * <p>Reaching it means a Transfer settled or was released twice, or against a reservation
	 * another Transfer had already consumed — a caller's mistake rather than a request an
	 * operator made, which is why it is not an {@link InsufficientFundsException}.
	 */
	private Money withinTheReservedAmount(Money amount) {
		if (reservedAmount.isLessThan(amount)) {
			throw new IllegalArgumentException(
					"reserved amount %s does not cover %s".formatted(reservedAmount, amount));
		}
		return amount;
	}
}

package hu.bankmonitor.payments.transfers.checks;

import hu.bankmonitor.payments.transfers.Transfer;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Objects;
import java.util.Set;

/**
 * The per-Transfer record of which Checks it requires and how each has been answered, and
 * the two operations this package exports: opening that record, and answering one Check in
 * it.
 *
 * <p>The two are the ledger's whole life and they are deliberately the only ways into it.
 * Every row a Transfer will ever have is written by {@link #openFor}, and the only thing
 * that happens to one afterwards is {@link #record} filling in its Verdict — there is no way
 * to add a row, remove one, or answer the same Check twice, which is what lets
 * {@link LedgerDecision#decide} read the rows as the whole truth about the Transfer.
 *
 * <p>The whole of what the Check Ledger is for rests on it being written <em>with</em> the
 * Transfer. A Transfer whose rows were written afterwards has a window in which it is
 * {@code PENDING} against an empty ledger — which is a Transfer nothing will ever settle,
 * expire or explain, holding an operator's funds until somebody notices. {@link
 * Propagation#MANDATORY} is that requirement stated to the container rather than left as a
 * convention for the caller to honour: this method cannot start a transaction of its own,
 * so the only way to call it is from inside one that is already writing the Transfer.
 *
 * <p>Being late is one way to that state and requiring nothing is the other: a policy that
 * names no Check makes {@link #openFor} write no rows and return, so the caller commits the
 * same stuck Transfer with every test still green. The refusal below is that second way
 * closed, at the only place that can see it happening.
 *
 * <p>The method is public on a package-private-by-default design because {@code
 * @Transactional} on a non-public method is silently ignored under proxy-based AOP — the
 * trap {@link hu.bankmonitor.payments} documents. The class is public for the ordinary
 * reason: {@code FundsReservation} is in the parent package and has to name it.
 */
@Component
public class CheckLedger {

	private final CheckPolicy policy;

	private final CheckLedgerRepository entries;

	CheckLedger(CheckPolicy policy, CheckLedgerRepository entries) {
		this.policy = policy;
		this.entries = entries;
	}

	/**
	 * Writes one outstanding row per Check the Transfer requires, in the caller's
	 * transaction.
	 *
	 * @param transfer a Transfer already written, so that the rows have an ID to point at
	 * @throws org.springframework.transaction.IllegalTransactionStateException if the caller
	 *                                                                         has no
	 *                                                                         transaction
	 *                                                                         open
	 * @throws IllegalStateException if the policy requires no Checks at all, which would
	 *                               write no rows and leave the caller committing the stuck
	 *                               Transfer described above
	 */
	@Transactional(propagation = Propagation.MANDATORY)
	public void openFor(Transfer transfer) {
		Long transferId = Objects.requireNonNull(transfer.getId(), "a ledger belongs to a written transfer");

		Set<Check> required = policy.requiredFor(transfer);
		if (required.isEmpty()) {
			throw new IllegalStateException("a transfer's check ledger is never empty");
		}

		for (Check check : required) {
			entries.save(CheckLedgerEntry.outstanding(transferId, check));
		}
	}

	/**
	 * Answers one outstanding Check and says what the whole ledger then supports, in the
	 * caller's transaction.
	 *
	 * <p>The answer is written by {@linkplain CheckLedgerRepository#answer a guarded update}
	 * rather than a read followed by a write, so two deliveries of the same Verdict leave one
	 * answer. A second delivery matching no row is not a refusal: nothing went wrong on the
	 * reporting side, and the caller still needs the decision back, because the delivery that
	 * did win may have been lost on the way home. What it does mean is that the decision here
	 * is made over what the ledger <em>holds</em>, never over the Verdict just handed in.
	 *
	 * <p><b>The rows are read after the update, and nothing may have read them before it.</b>
	 * A bulk update goes straight to the database and leaves the persistence context alone,
	 * so an entry loaded earlier in the same transaction would come back from
	 * {@link CheckLedgerRepository#findAllByTransferId} still carrying its old, unanswered
	 * Verdict — and a ledger whose last outstanding row looks outstanding decides {@code
	 * WAIT}, leaving a fully approved Transfer pending for ever. This is the only method that
	 * reads the rows, and it reads them here.
	 *
	 * <p>{@link Propagation#MANDATORY} for {@link #openFor}'s reason turned around: the
	 * decision returned here is acted on by moving money, and an answer committed separately
	 * from the movement it authorises is either a settled Transfer nobody paid or a payment
	 * against a ledger that does not record why.
	 *
	 * @return what the Transfer's ledger now supports, which the caller owns acting on
	 * @throws org.springframework.transaction.IllegalTransactionStateException if the caller
	 *                                                                         has no
	 *                                                                         transaction
	 *                                                                         open
	 * @throws CheckNotRequiredException if the Transfer's ledger has no row for that Check
	 * @throws IllegalArgumentException  if the Transfer has no ledger at all, which
	 *                                   {@link LedgerDecision#decide} refuses rather than
	 *                                   settles
	 */
	@Transactional(propagation = Propagation.MANDATORY)
	public LedgerDecision record(long transferId, Check check, Verdict verdict) {
		int answered = entries.answer(transferId, check, verdict);
		List<CheckLedgerEntry> ledger = entries.findAllByTransferId(transferId);

		if (answered == 0 && ledger.stream().noneMatch(entry -> entry.isFor(check))) {
			throw new CheckNotRequiredException(transferId, check);
		}
		return LedgerDecision.decide(ledger);
	}
}

package hu.bankmonitor.payments.transfers.checks;

import java.util.Collection;

/**
 * What a Transfer's Check Ledger says should happen to the Transfer next.
 *
 * <p>{@link #decide} is the whole of the orchestration rule, and it is a function of the
 * ledger rows and nothing else — no repository, no clock, no Transfer. That is a design
 * instruction rather than a testing convenience: the same three lines inside a service that
 * also loads rows and moves money would only be reachable through a database, and the
 * mixed-verdict case that matters most would be set up by writing four tables.
 *
 * <p>{@link CheckLedger#record} is the caller. It answers one Check, loads the rows and asks
 * here; {@code VerdictRecording} owns everything with a side effect. Two deliveries of the
 * same Verdict both reach this function and both get the same answer, because only the first
 * of them changed a row — which is what makes the second one safe to act on rather than
 * merely harmless.
 */
public enum LedgerDecision {

	/** Every Check has approved. The money moves, once. */
	SETTLE,

	/** A Check said no. The reservation is released and no money ever moved. */
	REJECT,

	/** Some Check has not answered, and none has refused. Nothing happens. */
	WAIT;

	/**
	 * Reads a Transfer's Check Ledger and says what follows from it.
	 *
	 * <p><b>Rejection wins immediately</b>, which is why it is asked first: once one Check
	 * has said no there is nothing the outstanding ones could say that changes the outcome,
	 * and waiting for them would hold an operator's funds against a Transfer already known
	 * to be dead. So a ledger of one rejection and three unanswered rows is {@link #REJECT},
	 * not {@link #WAIT}.
	 *
	 * <p>The second question is only whether anything is still outstanding, because the
	 * first has already excluded every rejection: answered and not rejected is approved.
	 *
	 * @param ledger every row the Transfer has, in any order
	 * @throws IllegalArgumentException if the ledger is empty. No rows at all satisfies
	 *                                  "nothing outstanding, nothing rejected" and would
	 *                                  settle a Transfer nobody checked. It cannot arise —
	 *                                  a Transfer is written with its rows in one
	 *                                  transaction, and {@link CheckLedger#openFor} refuses
	 *                                  a policy that requires none — so the only way to be
	 *                                  handed one is to have loaded the wrong Transfer's
	 *                                  ledger, and answering that with "move the money" is
	 *                                  the worst available guess.
	 */
	static LedgerDecision decide(Collection<CheckLedgerEntry> ledger) {
		if (ledger.isEmpty()) {
			throw new IllegalArgumentException("a transfer's check ledger is never empty");
		}
		if (ledger.stream().anyMatch(CheckLedgerEntry::isRejected)) {
			return REJECT;
		}
		return ledger.stream().allMatch(CheckLedgerEntry::isAnswered) ? SETTLE : WAIT;
	}
}

