1	package hu.bankmonitor.payments.transfers;
2	
3	import hu.bankmonitor.payments.accounts.InsufficientFundsException;
4	import hu.bankmonitor.testsupport.RowLockBarrier;
5	import org.junit.jupiter.api.DisplayName;
6	import org.junit.jupiter.api.Test;
7	import org.springframework.beans.factory.annotation.Autowired;
8	import org.springframework.context.annotation.Import;
9	
10	import java.time.Duration;
11	import java.util.ArrayList;
12	import java.util.List;
13	import java.util.concurrent.ExecutorService;
14	import java.util.concurrent.Executors;
15	import java.util.concurrent.Future;
16	import java.util.concurrent.TimeUnit;
17	import java.util.stream.Stream;
18	
19	import static hu.bankmonitor.payments.common.Currency.EUR;
20	import static org.assertj.core.api.Assertions.assertThat;
21	
22	/**
23	 * The two threads design decision 6 exists for: one Available Balance that cannot be spent
24	 * twice, and two Transfers in opposite directions that cannot wait on each other.
25	 *
26	 * <p>These are the tests the design's central integrity claim rests on, and both of them are
27	 * easy to write in a shape that proves nothing. Three traps, avoided deliberately:
28	 *
29	 * <ul>
30	 * <li><b>A transactional test method.</b> {@link ReservationScenario} is not annotated
31	 * {@code @Transactional}, so each thread's reservation really commits. Wrapped in one
32	 * transaction instead, the second thread would be looking at a connection that cannot see
33	 * the first thread's uncommitted work, and the race would be invisible rather than absent.
34	 * The price is emptying the tables by hand, which that class pays.
35	 * <li><b>Threads that never overlap.</b> Submitting two tasks does not make them concurrent:
36	 * on an in-memory database the first finishes in well under the time it takes to schedule the
37	 * second, and the second then reads a settled world.
38	 * <li><b>A latch in the wrong place.</b> Releasing both threads at the <em>start</em> of the
39	 * operation is not enough, and this was measured rather than assumed: with a start latch and
40	 * nothing else, {@link #opposingTransfersBetweenOnePairOfAccountsBothComplete} stayed green
41	 * after the ascending-ID rule was deleted from {@code AccountLocking}, because thread one
42	 * still committed before thread two acquired anything. {@link RowLockBarrier} moves the wait
43	 * to the only point where the ordering is observable, and its Javadoc is where that argument
44	 * lives.
45	 * </ul>
46	 *
47	 * <p>With the barrier in place both claims below are falsifiable, which is the only reason
48	 * to believe them: dropping {@code @Lock(PESSIMISTIC_WRITE)} fails
49	 * {@link #exactlyOneOfTwoConcurrentTransfersOutOfOneAccountSucceeds}, and locking by role
50	 * instead of by ascending ID fails
51	 * {@link #opposingTransfersBetweenOnePairOfAccountsBothComplete}.
52	 *
53	 * <p>Both tests run on H2, whose lock timeout is around a second where Postgres waits
54	 * indefinitely. Nothing here holds a lock for anything like that long — the whole transaction
55	 * is four statements against an in-memory table — but {@code docs/deferred.md} names running
56	 * this suite against Postgres as a production prerequisite rather than a nicety, and this is
57	 * the suite it means.
58	 */
59	@Import(RowLockBarrier.class)
60	class ConcurrentReservationsHoldTheBalanceTest extends ReservationScenario {
61	
62		private static final long LOWER_ID = 1L;
63		private static final long HIGHER_ID = 2L;
64	
65		/** Generous, because it is only ever reached by a deadlock, and then the test has failed. */
66		private static final Duration BEFORE_GIVING_UP = Duration.ofSeconds(10);
67	
68		@Autowired
69		private RowLockBarrier rowLocks;
70	
71		/**
72		 * Two Transfers of 150.00 against an Available Balance of 200.00: either alone is
73		 * covered, and the two together are not, so "both succeeded" is a distinguishable
74		 * outcome rather than an arithmetic coincidence.
75		 *
76		 * <p>Both halves of the claim are asserted here rather than split into a test of their
77		 * own, because only one of them can fail on its own. Two unlocked transactions do not
78		 * over-reserve — they <em>lose</em> one of the two updates, and the Reserved Amount lands
79		 * on 150.00 exactly as it should. A separate "the Account never reserves more than it
80		 * holds" test therefore stays green against a design with no locking at all, which is the
81		 * shape of test this ticket was warned about; the outcome count above is what catches it.
82		 */
83		@Test
84		@DisplayName("two concurrent Transfers out of one Account: exactly one succeeds and the balance holds")
85		void exactlyOneOfTwoConcurrentTransfersOutOfOneAccountSucceeds() throws Exception {
86			openAccount(LOWER_ID, 200_00L, EUR);
87			openAccount(HIGHER_ID, 0L, EUR);
88	
89			List<Attempt> attempts = race(
90					transferOf(150_00L, LOWER_ID, HIGHER_ID),
91					transferOf(150_00L, LOWER_ID, HIGHER_ID));
92	
93			assertThat(attempts).filteredOn(Attempt::succeeded).hasSize(1);
94			assertThat(attempts).filteredOn(attempt -> !attempt.succeeded())
95					.singleElement()
96					.extracting(Attempt::refusal)
97					.isInstanceOf(InsufficientFundsException.class);
98	
99			assertThat(transferRows()).singleElement()
100					.satisfies(row -> assertThat(row).containsEntry("STATUS", "PENDING"));
101	
102			assertThat(balanceOf(LOWER_ID)).as("no money moved").isEqualTo(200_00L);
103			assertThat(reservedAmountOf(LOWER_ID)).isEqualTo(150_00L);
104			assertThat(availableBalanceOf(LOWER_ID)).isNotNegative().isEqualTo(50_00L);
105		}
106	
107		/**
108		 * The demonstration the ascending-ID rule exists for, and the reason
109		 * {@link RowLockBarrier} is worth its weight. Held at their first lock until both have
110		 * asked for one, two role-ordered Transfers would each be holding what the other wants:
111		 * one thread on the lower Account waiting for the higher, the other the reverse. Ordered
112		 * by ID, both ask for the lower Account first, so the loser waits holding nothing and
113		 * there is no cycle to form.
114		 *
115		 * <p>A deadlock shows up here either as H2 refusing one of the two, which fails the
116		 * "neither direction is refused" assertion, or as two threads that never return, which
117		 * fails on {@link #BEFORE_GIVING_UP}.
118		 */
119		@Test
120		@DisplayName("opposing Transfers between one pair of Accounts both complete")
121		void opposingTransfersBetweenOnePairOfAccountsBothComplete() throws Exception {
122			openAccount(LOWER_ID, 500_00L, EUR);
123			openAccount(HIGHER_ID, 500_00L, EUR);
124	
125			List<Attempt> attempts = race(
126					transferOf(100_00L, LOWER_ID, HIGHER_ID),
127					transferOf(100_00L, HIGHER_ID, LOWER_ID));
128	
129			assertThat(attempts).allSatisfy(attempt -> {
130				assertThat(attempt.refusal()).as("neither direction is refused").isNull();
131				assertThat(attempt.transfer().getId()).as("both directions were written").isNotNull();
132			});
133	
134			assertThat(reservedAmountOf(LOWER_ID)).isEqualTo(100_00L);
135			assertThat(reservedAmountOf(HIGHER_ID)).isEqualTo(100_00L);
136			assertThat(balanceOf(LOWER_ID)).isEqualTo(500_00L);
137			assertThat(balanceOf(HIGHER_ID)).isEqualTo(500_00L);
138			assertThat(transferRows()).hasSize(2);
139		}
140	
141		/**
142		 * Runs both reservations on threads of their own, each held at its first row lock until
143		 * the other has reached one, and reports what each of them got. Waiting on the futures
144		 * with a timeout is what turns a deadlock from a suite that hangs into a test that fails.
145		 */
146		private List<Attempt> race(ReservationRequest first, ReservationRequest second) throws Exception {
147			rowLocks.holdEachThreadAtItsFirstRowLock(2);
148			ExecutorService threads = Executors.newFixedThreadPool(2);
149			try {
150				List<Future<Attempt>> attempts = Stream.of(first, second)
151						.map(request -> threads.submit(() -> attempt(request)))
152						.toList();
153	
154				List<Attempt> outcomes = new ArrayList<>();
155				for (Future<Attempt> attempt : attempts) {
156					outcomes.add(attempt.get(BEFORE_GIVING_UP.toSeconds(), TimeUnit.SECONDS));
157				}
158				return outcomes;
159			}
160			finally {
161				rowLocks.release();
162				threads.shutdownNow();
163			}
164		}
165	
166		private Attempt attempt(ReservationRequest request) {
167			try {
168				return new Attempt(reservation.reserve(request), null);
169			}
170			catch (RuntimeException refusal) {
171				return new Attempt(null, refusal);
172			}
173		}
174	
175		/** What one thread came back with: a Transfer or the reason there is none. */
176		private record Attempt(Transfer transfer, RuntimeException refusal) {
177	
178			boolean succeeded() {
179				return refusal == null;
180			}
181		}
182	}
