78		 * unimpeded, which is what leaves it free to reach for its second lock and find out
79		 * whether another thread is sitting on it.
80		 */
81		public void holdEachThreadAtItsFirstRowLock(int threads) {
82			everyThreadsFirstRowLock.set(new CountDownLatch(threads));
