101				awaitTheOthers(arrivals);
102			}
103			return sql;
104		}
105	
106		private static boolean isARowLock(String sql) {
107			return sql.toLowerCase().contains("for update");
108		}
109	
110		private static void awaitTheOthers(CountDownLatch arrivals) {
111			try {
112				arrivals.await(BEFORE_GIVING_UP.toSeconds(), TimeUnit.SECONDS);
113			}
114			catch (InterruptedException interrupted) {
