package hu.bankmonitor.payments.transfers.checks;

import hu.bankmonitor.payments.transfers.Transfer;
import org.springframework.stereotype.Component;

import java.util.EnumSet;
import java.util.Set;

/**
 * Which Checks a Transfer has to pass before it can settle.
 *
 * <p>The one place that answer is given. Adding a condition to this payment gateway is a
 * constant on {@link Check}, a line here and a row in the ledger — no new endpoint, no new
 * state, and nothing in the settlement rule to revisit. That extensibility is the whole
 * reason ADR-0001 chose an asynchronous lifecycle over settling inside the request.
 */
@Component
class CheckPolicy {

	/**
	 * Every Transfer requires both Checks today, so the Transfer goes unread — and the
	 * parameter is still the point. A policy that cannot see the Transfer cannot grow the
	 * first rule that depends on one ("manual approval above ten thousand", "fraud
	 * screening only across Currencies"), and this ticket is the one that gets to choose
	 * the signature while it has no other caller to break.
	 *
	 * <p>Deliberately not {@code EnumSet.allOf(Check.class)}, which would be shorter and
	 * would silently apply the first conditional Check to every Transfer ever written. What
	 * Checks <em>exist</em> and what a given Transfer <em>requires</em> are two questions,
	 * and this class only answers the second.
	 */
	Set<Check> requiredFor(Transfer transfer) {
		return EnumSet.of(Check.FRAUD, Check.MANUAL_APPROVAL);
	}
}

package hu.bankmonitor.payments.transfers.checks;

/**
 * A condition a Transfer must satisfy before it can settle, answered by a party outside
 * this context.
 *
 * <p>A human approver and an automated service are the same kind of thing here: each
 * answers one of these constants for one Transfer, through the same operation. That
 * indistinguishability is what the asynchronous lifecycle was chosen for — a new condition
 * is a constant here and a line in {@link CheckPolicy}, not a new mechanism.
 *
 * <p>The constants are stored by name, so they are part of the schema: {@code
 * V4__check_ledger.sql} lists them in a check constraint, and renaming one is a migration
 * rather than a refactor.
 */
public enum Check {

	/** Automated fraud screening, answered by a service the outbox pushes the request to. */
	FRAUD,

	/** A person signing off in a back-office tool, reporting through the same endpoint. */
	MANUAL_APPROVAL
}

package hu.bankmonitor.payments.transfers.checks;

/**
 * A {@link Check}'s answer for one Transfer.
 *
 * <p>There are two answers and there is no third. A Check that has not answered has no
 * Verdict at all, which the ledger records as an absent column rather than as a constant
 * here — {@link CheckLedgerEntry} has the argument for that, and it is a claim about the
 * domain: "not yet answered" is the absence of an answer, not one of the answers.
 *
 * <p>The two are not symmetrical in what they cost. {@link #APPROVED} advances nothing on
 * its own — it is the other rows that decide — while {@link #REJECTED} ends the Transfer
 * whatever the rest of the ledger says. {@link LedgerDecision} is where that asymmetry is
 * written down.
 */
public enum Verdict {

	/** This Check is satisfied. The Transfer settles once every other Check agrees. */
	APPROVED,

	/** This Check says no, and that is the whole answer: the Transfer is rejected. */
	REJECTED
}

