package hu.bankmonitor.payments.transfers;

import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.Repository;

import java.util.Optional;

import static jakarta.persistence.LockModeType.PESSIMISTIC_WRITE;

/**
 * Reading a {@link Transfer} and advancing it, package-private so that reaching it from
 * another slice does not compile (design decision 30). Writing one is
 * {@link TransferCreation}'s, and the split is deliberate — that interface says why.
